/**
 * @brief State used to check that a load can keep referring to its original
 * slot.
 */
typedef struct {
  IrFunction* fn;
  const CgPlacement* placement;
  unsigned char* visited;
  IrValueId value;
  IrStackSlotId slot;
} CgSlotAlias;

/**
 * @brief Test whether an operand directly references the given value ID.
 *
 * @param operand IR operand to inspect.
 * @param value IR value ID to look for.
 * @return True if the operand directly references the value.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Eliminate producer stores and read slots directly until their next
// write.
static bool cg_uses_value(IrOperand operand, IrValueId value) {
  return operand.type == IR_OP_VALUE && operand.value.id == value;
}

/**
 * @brief Count references to a value in an instruction's operands.
 *
 * @param inst IR instruction being analyzed or emitted.
 * @param value IR value ID to look for.
 * @return Number of references to the value in the instruction.
 */
static size_t cg_instruction_uses(IrInstruction* inst, IrValueId value) {
  switch (ir_get_instruction_class(inst)) {
    case IR_INST_CLASS_UNARY:
      return cg_uses_value(inst->operands.unary.operand, value);

    case IR_INST_CLASS_BINARY:
      return (size_t)cg_uses_value(inst->operands.binary.left, value) +
             cg_uses_value(inst->operands.binary.right, value);

    case IR_INST_CLASS_STORE:
      return cg_uses_value(inst->operands.store.source, value);

    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Remove builtin functions from the IR altogether (they should now
    // be handled by lowering to allow for their optimalization, no?). Propagate
    // these changes to the relevant systems (codegen, optimizer)" Changes:
    // Consider substring operands when planning temporary placement.
    case IR_INST_CLASS_TERNARY: {
      size_t uses = 0;

      for (size_t i = 0; i < 3; i++)
        uses += cg_uses_value(inst->operands.ternary[i], value);

      return uses;
    }

    case IR_INST_CLASS_CALL: {
      size_t uses = 0;

      for (size_t a = 0; a < inst->operands.call.arg_count; a++)
        uses += cg_uses_value(inst->operands.call.args[a], value);

      return uses;
    }

    default:
      return 0;
  }
}

/**
 * @brief Check whether the block's terminator reads the given value.
 *
 * @param term Block terminator to inspect.
 * @param value IR value ID to look for.
 * @return True if the terminator reads the value.
 */
static bool cg_terminator_uses(const IrBlockTerminator* term, IrValueId value) {
  switch (term->type) {
    case IR_TERMINATOR_CONDITIONAL:
      return cg_uses_value(term->value.conditional_target.condition, value);
    case IR_TERMINATOR_RETURN:
      return cg_uses_value(term->value.return_value, value);
    case IR_TERMINATOR_EXIT:
      return cg_uses_value(term->value.exit_code, value);
    default:
      return false;
  }
}

void cg_plan_stores(IrFunction* fn,
                    IrBlock* block,
                    const size_t* uses,
                    CgPlacement* placement) {
  IrInstructionArray* instructions = &block->instructions;
  for (size_t i = 0; i + 1 < instructions->count; i++) {
    const IrInstruction* current = &instructions->data[i];
    const IrInstruction* next = &instructions->data[i + 1];
    IrValueId value = current->result;

    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Remove builtin functions from the IR altogether (they should
    // now be handled by lowering to allow for their optimalization, no?).
    // Propagate these changes to the relevant systems (codegen, optimizer)"
    // Changes: Keep checked string recipes out of early destination
    // placement.
    if (value != IR_INVALID_ID && uses[value] == 1 &&
        next->type == IR_INST_STORE &&
        cg_uses_value(next->operands.store.source, value) &&
        current->type != IR_INST_FLOOR && current->type != IR_INST_CALL &&
        current->type != IR_INST_ORD && current->type != IR_INST_STR_SUB &&
        current->type != IR_INST_LOAD && !cg_ordered_inclusive(fn, current))
      placement[value].slot = next->operands.store.target;
  }
}

/**
 * @brief Check that no path can overwrite the slot before a use of the loaded
 * snapshot.
 *
 * @param alias Slot, captured value, placement, and traversal state.
 * @param id ID of the current block.
 * @param start Index of the first instruction to inspect.
 * @param dirty Whether this path already overwrote the slot.
 * @return True if the searched paths preserve the captured value through every
 * use.
 */
// A value may alias its slot only while no path from the load to a use
// overwrites that slot.
static bool cg_alias_path(CgSlotAlias* alias,
                          IrBlockId id,
                          size_t start,
                          bool dirty) {
  if (id >= alias->fn->blocks.count)
    return true;

  if (start == 0) {
    // A clean visit cannot rule out a later path to this block after a write.
    unsigned mask = dirty ? 2 : 1;

    if (alias->visited[id] & mask)
      return true;

    alias->visited[id] |= mask;
  }

  IrBlock* block = &alias->fn->blocks.data[id];
  for (size_t i = start; i < block->instructions.count; i++) {
    IrInstruction* inst = &block->instructions.data[i];

    // A backedge that executes the load again captures a new slot value.
    if (inst->result == alias->value)
      return true;

    if (dirty && cg_instruction_uses(inst, alias->value))
      return false;

    if ((inst->type == IR_INST_STORE &&
         inst->operands.store.target == alias->slot) ||
        (inst->result != IR_INVALID_ID && inst->type != IR_INST_LOAD &&
         alias->placement[inst->result].slot == alias->slot))
      dirty = true;
  }

  IrBlockTerminator* term = &block->terminator;

  if (dirty && cg_terminator_uses(term, alias->value))
    return false;

  if (term->type == IR_TERMINATOR_JUMP)
    return cg_alias_path(alias, term->value.jump_target, 0, dirty);

  if (term->type == IR_TERMINATOR_CONDITIONAL) {
    return cg_alias_path(alias, term->value.conditional_target.true_target, 0,
                         dirty) &&
           cg_alias_path(alias, term->value.conditional_target.false_target, 0,
                         dirty);
  }

  return true;
}

void cg_plan_loads(IrFunction* fn,
                   IrBlockId id,
                   const size_t* uses,
                   CgPlacement* placement,
                   unsigned char* visited) {
  IrInstructionArray* instructions = &fn->blocks.data[id].instructions;
  for (size_t i = 0; i < instructions->count; i++) {
    const IrInstruction* load = &instructions->data[i];

    if (load->type != IR_INST_LOAD || load->result == IR_INVALID_ID ||
        !uses[load->result])
      continue;

    memset(visited, 0, fn->blocks.count);
    CgSlotAlias alias = {fn, placement, visited, load->result,
                         load->operands.load.source};

    if (cg_alias_path(&alias, id, i + 1, false))
      placement[load->result].slot = alias.slot;
  }
}

