// Changes: Reuse local storage when a value is consumed in the same block.
void cg_reuse_locals(IrBlock* block,
                     const size_t* uses,
                     CgPlacement* placement) {
  IrInstructionArray* instructions = &block->instructions;
  // Choose storage using the lifetime of each value within this block.
  for (size_t i = 0; i < instructions->count; i++) {
    IrInstruction* inst = &instructions->data[i];
    IrValueId value = inst->result;

    if (value == IR_INVALID_ID || inst->type == IR_INST_FLOOR ||
        placement[value].slot != IR_INVALID_ID || placement[value].on_stack ||
        uses[value] != 1)
      continue;

    size_t last_use = i + 1;

    while (last_use < instructions->count &&
           !cg_instruction_uses(&instructions->data[last_use], value))
      last_use++;

    if (last_use == instructions->count)
      continue;

    for (size_t j = 0; j < i; j++) {
      IrValueId previous = instructions->data[j].result;

      if (previous == IR_INVALID_ID)
        continue;

      size_t local = placement[previous].local;
      size_t end = placement[local].live_through;

      if (end != 0 && end < i) {
        placement[value].local = local;
        break;
      }
    }

    placement[placement[value].local].live_through = last_use;
  }
}

bool cg_elides_copy(const IrInstruction* inst, const CgPlacement* placement) {
  if (inst->type == IR_INST_LOAD)
    return inst->result != IR_INVALID_ID &&
           placement[inst->result].slot != IR_INVALID_ID;

  if (inst->type == IR_INST_STORE) {
    IrOperand source = inst->operands.store.source;
    return source.type == IR_OP_VALUE &&
           placement[source.value.id].slot == inst->operands.store.target;
  }

  return false;
}
